CREATE TABLE IF NOT EXISTS regions(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS parks(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,region_id INTEGER NOT NULL REFERENCES regions(id),address TEXT NOT NULL,area INTEGER NOT NULL CHECK(area>0),archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)));
CREATE TABLE IF NOT EXISTS facilities(id INTEGER PRIMARY KEY,park_id INTEGER NOT NULL REFERENCES parks(id),name TEXT NOT NULL,kind TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)));
CREATE TABLE IF NOT EXISTS inspections(id INTEGER PRIMARY KEY,facility_id INTEGER NOT NULL REFERENCES facilities(id),on_date TEXT NOT NULL,condition TEXT NOT NULL CHECK(condition IN('Baik','Perlu Perawatan','Rusak')),note TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS schedules(id INTEGER PRIMARY KEY,facility_id INTEGER NOT NULL REFERENCES facilities(id),starts_on TEXT NOT NULL,ends_on TEXT NOT NULL,task TEXT NOT NULL,canceled INTEGER NOT NULL DEFAULT 0 CHECK(canceled IN(0,1)),CHECK(ends_on>=starts_on));
CREATE TABLE IF NOT EXISTS activities(id INTEGER PRIMARY KEY,schedule_id INTEGER NOT NULL REFERENCES schedules(id),on_date TEXT NOT NULL,progress INTEGER NOT NULL CHECK(progress BETWEEN 0 AND 100),note TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
